use xiom.io;

use xiom.string;
fn shift_char(c: Char, shift: Int) -> Char {
  if c >= 'A' && c <= 'Z' {
    let pos = c as Int - 'A' as Int;
    let new_pos = (pos + shift + 26) % 26;
    return ('A' as Int + new_pos) as Char;
  };
  if c >= 'a' && c <= 'z' {
    let pos = c as Int - 'a' as Int;
    let new_pos = (pos + shift + 26) % 26;
    return ('a' as Int + new_pos) as Char;
  };
  c
}

fn caesar_encrypt(text: Str, shift: Int) -> Str {
  let mut result = "";
  let mut i = 0;
  while i < text.len() {
    result = string.str_concat(result, string.from_char(shift_char(text.get(i).unwrap(), shift)));
    i += 1;
  };
  result
}

fn caesar_decrypt(text: Str, shift: Int) -> Str {
  caesar_encrypt(text, -shift)
}

fn main() -> Int {
  let encrypted = caesar_encrypt("HELLO", 3);
  io.println(encrypted.to_str());
  io.println(caesar_decrypt(encrypted, 3));
  return 0;
}
